//! The acceptance test `ARCHITECTURE.md` §7 asks for: every translation in
//! `parser.md` §6.3 must select **the same node set** as the cssselect-derived
//! XPath does in Python.
//!
//! `testdata/css_selection.jsonl` is generated by
//! `tools/gen_selection_corpus.py` against the real `the reference implementation` +
//! `lxml` + `cssselect`, over `testdata/fixture.html`. Each row records the
//! translated XPath (informational), cssselect's canonical parts, and the
//! node-set lxml returned, with every entry identified by an
//! `ElementTree.getpath()`-style path so the comparison does not depend on
//! either side's serialiser.
//!
//! Regenerate with:
//!
//! ```text
//! path/to/python crates/browser-selectors/tools/gen_selection_corpus.py
//! ```

use std::collections::BTreeMap;

use browser_dom::{Document, NodeRef, ParseOptions};
use browser_selectors::matching::{MatchValue, TextRole};
use browser_selectors::parse::parse_selector;
use serde_json::Value;

const FIXTURE: &str = include_str!("../testdata/fixture.html");
const CORPUS: &str = include_str!("../testdata/css_selection.jsonl");

/// The parser flags `reference/parser.py:157` passes to lxml, which are also
/// `browser-dom`'s defaults.
fn document() -> Document {
    Document::parse_with(FIXTURE, &ParseOptions::new())
}

/// `lxml.etree.ElementTree.getpath()`: `/html/body/div[2]/span`, with the
/// `[n]` suffix omitted when the element is the only one of its name among its
/// siblings.
fn getpath(node: NodeRef<'_>) -> String {
    let mut segments: Vec<String> = Vec::new();
    let mut current = Some(node);
    while let Some(el) = current {
        if !el.is_element() {
            break;
        }
        let tag = el.tag();
        let siblings = el.parent().map_or(1, |p| {
            p.element_children().filter(|s| s.tag() == tag).count()
        });
        if siblings > 1 {
            segments.push(format!("{tag}[{}]", el.nth_of_type()));
        } else {
            segments.push(tag.to_owned());
        }
        current = el.parent_element();
    }
    segments.reverse();
    format!("/{}", segments.join("/"))
}

/// Render our results in exactly the shape the generator emitted.
fn describe(m: &browser_selectors::matching::Match<'_>) -> BTreeMap<String, Value> {
    let mut map = BTreeMap::new();
    match m.value() {
        MatchValue::Element => {
            map.insert("kind".into(), Value::from("element"));
            map.insert("path".into(), Value::from(getpath(m.element())));
        }
        MatchValue::Text { node, role } => {
            map.insert("kind".into(), Value::from("text"));
            map.insert("owner".into(), Value::from(getpath(m.element())));
            map.insert(
                "role".into(),
                Value::from(match role {
                    TextRole::Text => "text",
                    TextRole::Tail => "tail",
                }),
            );
            map.insert(
                "value".into(),
                Value::from(node.as_text().unwrap_or_default()),
            );
        }
        MatchValue::Attr { name, value } => {
            map.insert("kind".into(), Value::from("attr"));
            map.insert("owner".into(), Value::from(getpath(m.element())));
            map.insert("name".into(), Value::from(name.to_string()));
            map.insert("value".into(), Value::from(*value));
        }
    }
    map
}

fn expected(row: &Value) -> Vec<BTreeMap<String, Value>> {
    row["results"]
        .as_array()
        .expect("results is an array")
        .iter()
        .map(|entry| {
            entry
                .as_object()
                .expect("an object")
                .iter()
                .map(|(k, v)| (k.clone(), v.clone()))
                .collect()
        })
        .filter(|entry: &BTreeMap<String, Value>| !is_blank_text(entry))
        .collect()
}

/// `browser-dom` deviation #3 (see `crates/browser-dom/API.md`): our
/// `remove_blank_text` deletes *every* whitespace-only text node, while
/// libxml2's `areBlanks()` keeps a few of them in mixed-content positions. The
/// difference is only ever visible in `::text` results that are pure
/// whitespace — which the reference implementation's own `get_all_text(valid_values=True)` drops
/// anyway — so both sides are filtered before comparison and the divergence
/// stays legible in the corpus file.
fn is_blank_text(entry: &BTreeMap<String, Value>) -> bool {
    entry.get("kind").and_then(Value::as_str) == Some("text")
        && entry
            .get("value")
            .and_then(Value::as_str)
            .is_some_and(|v| v.trim().is_empty())
}

fn rows() -> impl Iterator<Item = Value> {
    CORPUS
        .lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| serde_json::from_str(line).expect("valid JSON line"))
}

#[test]
fn corpus_is_not_accidentally_empty() {
    let n = rows().count();
    assert!(n >= 100, "expected the full corpus, got {n} rows");
}

/// Resolve a row's `context_path` (an lxml `getpath`) back to a node.
fn node_at<'a>(doc: &'a Document, path: &str) -> NodeRef<'a> {
    doc.elements()
        .find(|e| getpath(*e) == path)
        .unwrap_or_else(|| panic!("no element at {path}"))
}

#[test]
fn every_selector_selects_the_same_node_set_as_lxml() {
    let doc = document();
    let root = doc.root();
    let mut checked = 0usize;

    for row in rows() {
        let selector = row["selector"].as_str().expect("a selector");
        if row.get("unsupported_by_cssselect").is_some() {
            // No oracle; assert only that we accept it (Selectors Level 4).
            assert!(
                parse_selector(selector).is_ok(),
                "{selector} should still parse"
            );
            continue;
        }

        // A row with a `context` was evaluated from that element in Python,
        // which is what `Node::css()` does — see the scoping notes in
        // `impl_selector`.
        let from = row
            .get("context_path")
            .and_then(Value::as_str)
            .map_or(root, |path| node_at(&doc, path));

        let group =
            parse_selector(selector).unwrap_or_else(|e| panic!("{selector} should parse, got {e}"));
        let got: Vec<_> = group
            .select(from)
            .iter()
            .map(describe)
            .filter(|entry| !is_blank_text(entry))
            .collect();
        let want = expected(&row);
        assert_eq!(
            got,
            want,
            "\nselector: {selector}\ncontext:  {}\nxpath:    {}\n",
            row.get("context")
                .and_then(Value::as_str)
                .unwrap_or("<root>"),
            row["xpath"].as_str().unwrap_or("")
        );
        checked += 1;
    }
    assert!(checked >= 100, "only {checked} selectors were compared");
}

#[test]
fn canonical_parts_have_the_same_arity_as_cssselects() {
    for row in rows() {
        let selector = row["selector"].as_str().expect("a selector");
        let Some(canonical) = row.get("canonical").and_then(Value::as_array) else {
            continue;
        };
        let group = parse_selector(selector).expect("parses");
        assert_eq!(
            group.canonical_parts().len(),
            canonical.len(),
            "group splitting must agree with cssselect for {selector}"
        );
        // The identifiers must round-trip through our own parser unchanged.
        for part in group.canonical_parts() {
            let reparsed = parse_selector(&part).expect("canonical form reparses");
            assert_eq!(reparsed.canonical(), part, "not a fixed point: {part}");
        }
    }
}

#[test]
fn getpath_matches_the_generators_paths() {
    // A guard on the test's own oracle: every path the corpus mentions must be
    // reachable by walking our tree.
    let doc = document();
    let known: std::collections::HashSet<String> = doc.elements().map(getpath).collect();
    for row in rows() {
        for entry in row["results"].as_array().into_iter().flatten() {
            let path = entry
                .get("path")
                .or_else(|| entry.get("owner"))
                .and_then(Value::as_str)
                .expect("a path");
            assert!(known.contains(path), "unknown path {path} in the corpus");
        }
    }
}
